(function(){
'use strict';
const C=WorkshopCore,D=JSON.parse(document.getElementById('workshop-data').textContent);
const KEY='el-bolson-workshop-v3'+(document.getElementById('initial-state').dataset.storageId||''),BACKUP=KEY+'-previous';
let TODAY=C.today();
try{const theme=localStorage.getItem(KEY+'-theme');if(['light','dark'].includes(theme))document.documentElement.dataset.theme=theme;}catch{}
const $=s=>document.querySelector(s),byId=Object.fromEntries(D.tasks.map(t=>[t.id,t])),itemById=Object.fromEntries(D.catalog.map(t=>[t.id,t])),modById=Object.fromEntries(D.modules.map(m=>[m.id,m]));
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n);
const usd=n=>n===null?'Требуется смета':'US$ '+new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n);
const ars=n=>'ARS '+new Intl.NumberFormat('es-AR',{maximumFractionDigits:2}).format(n);
const date=(s,long=false)=>s?new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:long?'long':'short',year:'numeric',timeZone:'UTC'}).format(new Date(C.stamp(s))):'—';
const safeURL=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const link=(url,label)=>`<a href="${h(safeURL(url))}" target="_blank" rel="noopener noreferrer">${h(label)}</a>`;
let state,forecast,currentTab='today',month=(TODAY<'2026-10-10'?'2026-10-10':TODAY).slice(0,7),selectedDate=TODAY,calendarMode='baseline',calendarView='month';
let taskFilter='',buyFilter='',buyQuery='',buyScope='active',toastTimer,loadWarning='',storageFailed=false,pendingExternal=null;
try{C.validateData(D);const embedded=JSON.parse($('#initial-state').textContent);const saved=localStorage.getItem(KEY);state=saved?C.validateState(JSON.parse(saved),D):embedded?C.validateState(embedded,D):C.defaults(D);}catch(e){state=C.defaults(D);loadWarning='Сохранённые данные не удалось загрузить: '+e.message+'. Исходная запись оставлена в браузере; можно скачать её в «Мой график».';storageFailed=true;}
if(!state.baseline){state.baseline=C.makeBaseline(D,state);state.revision=state.baseline.revision;}
function compute(){forecast=C.schedule(D,state.config,{progress:state.progress,overrides:state.overrides,start:state.config.start>TODAY?state.config.start:TODAY,forecast:true});}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function persist(message='Сохранено в этом браузере'){
  try{if(storageFailed)throw new Error('Сначала экспортируй данные или восстанови запись');const previous=localStorage.getItem(KEY);if(previous)localStorage.setItem(BACKUP,previous);localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent=message;$('#save-status').className='';}catch(e){$('#save-status').textContent='Изменения только в памяти — скачай резервную копию';$('#save-status').className='save-warn';}
}
function changed(){compute();persist();renderHeader();renderCurrent();}
function progress(id){return state.progress[id]||{percent:0,actualHours:0};}
function taskCost(id){return C.effort(byId[id],state.config,state.overrides);}
function activeTasks(){return C.enabledTasks(D,state.config);}
function taskReady(t){return t.deps.every(id=>progress(id).percent===100);}
function releaseDate(t){const o=state.overrides[t.id]||{},dep=t.deps.length?t.deps.map(id=>progress(id).completed).filter(Boolean).sort().at(-1):state.config.start;return [C.addDays(dep||state.config.start,o.lag??t.lag),o.notBefore||''].sort().at(-1);}
function firstForModule(module,schedule=forecast){return activeTasks().filter(t=>t.module===module).map(t=>schedule.starts[t.id]).filter(Boolean).sort()[0];}
function taskButton(id,label='Открыть'){return `<button class="small" data-task="${h(id)}">${h(label)}</button>`;}
function taskRow(t,suffix=''){
 const p=progress(t.id),done=p.percent===100,baseEnd=state.baseline.finish[t.id],late=baseEnd&&baseEnd<TODAY&&!done;
 return `<div class="task-row"><div><div class="task-title">${h(t.title)}</div><div class="detail">${h(modById[t.module].title)} · ${number(p.percent||0)}% · ${number(taskCost(t.id))} ч с запасом ${suffix?`· ${h(suffix)}`:''}</div><div class="detail">${done?`<span class="ok-text">Проверено ${date(p.completed)}</span>`:late?`<span class="negative">План был до ${date(baseEnd)}</span>`:!taskReady(t)?'Сначала предыдущие задачи':releaseDate(t)>TODAY?'Ожидание до '+date(releaseDate(t)):`Прогноз: ${date(forecast.starts[t.id])} — ${date(forecast.finish[t.id])}`}</div></div>${taskButton(t.id,done?'Посмотреть':'Отметить')}</div>`;
}
function metric(label,value,note,cls=''){return `<div class="metric"><div class="metric-label">${h(label)}</div><div class="metric-value ${cls}">${value}</div><div class="metric-note">${note}</div></div>`;}
function renderHeader(){
 $('#stamp-start').textContent=date(state.config.start);$('#stamp-hours').textContent=number(state.config.hours.reduce((a,b)=>a+b,0))+' ч / неделю · запас '+state.config.buffer+'%';$('#stamp-end').textContent=date(forecast.end);
 if(loadWarning){$('#save-status').textContent='Не удалось загрузить сохранение — см. «Мой график»';$('#save-status').className='save-warn';}
}
function trend(){
 const start=state.baseline.config.start,total=Object.values(state.baseline.efforts).reduce((a,b)=>a+b,0)||1,end=state.baseline.end,span=Math.max(1,C.dayDiff(end,start));
 const bins=24,columns=[];
 for(let i=0;i<bins;i++){const d=C.addDays(start,Math.round(span*i/(bins-1)));const planned=state.baseline.segments.filter(s=>s.date<=d).reduce((a,s)=>a+s.hours,0);const at={};for(const e of [...(state.log||[])].sort((a,b)=>a.date.localeCompare(b.date)))if(e.date<=d)at[e.id]=e.percent;const earned=state.baseline.taskIds.reduce((a,id)=>a+(state.baseline.efforts[id]||0)*(at[id]||0)/100,0);columns.push(`<div class="trend-col" title="${h(date(d))}: план ${number(planned)} ч, зафиксировано ${number(earned)} ч"><span style="height:${100*planned/total}%"></span>${d<=TODAY?`<span class="actual" style="height:${100*earned/total}%"></span>`:''}</div>`);}
 return `<div class="legend"><span><i></i>Исходный план</span><span class="actual"><i></i>Готовность по журналу отметок</span></div><div class="trend" role="img" aria-label="Накопленный план работ и зафиксированная готовность">${columns.join('')}</div><div class="trend-labels"><span>${date(start)}</span><span>${date(end)}</span></div>`;
}
function renderToday(){
 const m=C.metrics(D,state,TODAY),b=C.budget(D,state),delta=m.delta,complete=activeTasks().filter(t=>progress(t.id).percent===100).length;
 const shift=C.dayDiff(forecast.end,state.baseline.end),next=activeTasks().filter(t=>progress(t.id).percent<100&&taskReady(t)&&releaseDate(t)<=TODAY).slice(0,4);
 const nextDate=forecast.segments.find(s=>s.date>=TODAY)?.date;
 const upcoming=nextDate?forecast.segments.filter(s=>s.date===nextDate):[];
 const scheduleConfig=c=>JSON.stringify([c.start,c.hours,c.buffer,c.modules,c.exceptions]);const dirty=scheduleConfig(state.config)!==scheduleConfig(state.baseline.config)||JSON.stringify(state.overrides)!==JSON.stringify(state.baseline.overrides);
 const purchases=upcoming.flatMap(s=>byId[s.id].items).filter((id,i,a)=>a.indexOf(id)===i).map(id=>itemById[id]).filter(i=>i.kind!=='have'&&!['owned','bought','built','tested','mastered'].includes(state.items[i.id]?.status));
 $('#panel-today').innerHTML=`<div class="row spread"><div><h2>Ближайшая работа</h2><p class="subtle">${date(TODAY,true)} · план сравнивается с концом ${date(m.cutoff)}</p></div><button data-go="settings">Настроить мой график</button></div>
 ${loadWarning?`<div class="notice warn">${h(loadWarning)}</div>`:''}
 ${dirty?'<div class="notice">График или оценки изменены. Прогноз уже обновлён, исходный план сохранён для честного сравнения. Новую точку отсчёта можно явно установить в «Мой график».</div>':''}
 <div class="metrics">${metric(delta<-.01?'Отставание':delta>.01?'Опережение':'По плану',(delta>0?'+':'')+number(delta)+' ч',`В объёме принятой работы · примерно ${number(Math.abs(m.sessionDelta))} рабочих сессий`,delta<0?'negative':delta>0?'positive':'')}${metric('Готовность',number(m.percent)+'%',`${state.baseline.taskIds.filter(id=>progress(id).percent===100).length} из ${state.baseline.taskIds.length} задач исходного плана · ${number(m.earned)} / ${number(m.total)} плановых часов`)}${metric('Прогноз завершения',date(forecast.end),shift===0?'Совпадает с исходным планом':`${Math.abs(shift)} календарных дней ${shift>0?'позже':'раньше'} исходного плана`,shift>0?'negative':'')}${metric('Фактически оплачено',usd(b.actual),`${b.records} записей · только введённые платежи`)}</div>
 <div class="two-col"><div><div class="box"><div class="box-title"><h3>${nextDate===TODAY?'Сегодня по прогнозу':nextDate?'Следующая сессия · '+date(nextDate):'Все выбранные задачи завершены'}</h3><button class="small" data-go="calendar">В календарь</button></div>${upcoming.length?upcoming.map(s=>taskRow(byId[s.id],number(s.hours)+' ч в этой сессии')).join(''):'<p class="empty">Выбери новое направление или займись собственным проектом.</p>'}</div>
 <div class="box"><h3>Можно начать сейчас</h3>${next.length?next.map(t=>taskRow(t)).join(''):'<p class="empty">Сейчас нет задач с выполненными предшественниками и истёкшим ожиданием. Ближайшая плановая сессия показана выше.</p>'}</div></div>
 <div><div class="box"><h3>Что подготовить к следующей сессии</h3>${purchases.length?`<ul class="mini-list">${purchases.map(i=>`<li><div class="row spread"><span>${h(i.title)}</span><button class="small" data-item="${i.id}">Учесть</button></div><div class="note">${C.itemBudget(i,state)===null?'Цена ещё не подтверждена':usd(C.itemBudget(i,state))+' · ориентир'}${i.quote?.partial?' · часть комплекта':''}</div></li>`).join('')}</ul>`:'<p class="empty">По привязанным позициям новых закупок нет. Материалы и исправность инструмента проверь перед работой.</p>'}</div>
 <div class="box"><h3>Ритм на дистанции</h3>${trend()}<p class="note">Готовность учитывает результат, а не количество покупок. Фактически затрачено ${number(m.actual)} ч. Часы факта вводятся отдельно: долго работать и закончить задачу — разные показатели.</p></div>
 ${m.late.length?`<div class="box"><h3>Незакончено к исходной дате · ${m.late.length}</h3>${m.late.slice(0,3).map(id=>taskRow(byId[id])).join('')}</div>`:''}</div></div>
 <div class="notice">Первый вариант расписания рассчитан на одного человека. Часы — начальные оценки с запасом ${state.config.buffer}%. В карточке задачи можно изменить трудоёмкость и ожидаемую дату поставки. Покупка инструмента сама по себе не завершает работу.</div>`;
}
function calendarSchedule(){return calendarMode==='baseline'?state.baseline:forecast;}
function renderCalendar(){
 const sc=calendarSchedule(),first=month+'-01',start=C.addDays(first,-((C.weekday(first)+6)%7));
 const perDay={};for(const s of sc.segments)(perDay[s.date]??=[]).push(s);
 const weekNames=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'];let cells=weekNames.map(w=>`<div class="weekday">${w}</div>`).join('');
 for(let i=0;i<42;i++){const day=C.addDays(start,i),segs=perDay[day]||[],hours=segs.reduce((a,s)=>a+s.hours,0),done=segs.length&&segs.every(s=>progress(s.id).percent===100),late=day<TODAY&&segs.some(s=>progress(s.id).percent<100),max=Math.max(1,C.capacity(sc.config||state.config,day));
 cells+=`<button class="day ${day.slice(0,7)!==month?'outside':''} ${day===TODAY?'today':''} ${selectedDate===day?'selected':''} ${done?'done':''} ${late?'late':''}" data-date="${day}" aria-label="${h(date(day,true))}, ${number(hours)} плановых часов, ${segs.length} задач" aria-pressed="${selectedDate===day}"><span class="number">${Number(day.slice(8))}</span><span class="dayhours">${hours?number(hours)+' ч':'—'}</span>${segs[0]?`<span class="day-task">${h(byId[segs[0].id].title)}</span>`:''}${segs.length>1?`<span class="dayhours">ещё ${segs.length-1}</span>`:''}<span class="day-dot"><span style="width:${Math.min(100,hours/max*100)}%"></span></span></button>`;
 }
 const selected=perDay[selectedDate]||[],days=Object.keys(perDay).filter(d=>d.slice(0,7)===month).sort();
 $('#panel-calendar').innerHTML=`<h2>Работа по дням</h2><p class="lede">Исходный календарь остаётся точкой отсчёта. Прогноз распределяет остаток работ с сегодняшнего дня по твоим часам и зависимостям.</p>
 <div class="toolbar"><button id="prev-month" aria-label="Предыдущий месяц">←</button><label class="field">Месяц<input type="month" id="calendar-month" value="${month}" min="2000-01" max="2190-12"></label><button id="next-month" aria-label="Следующий месяц">→</button><button id="calendar-today">Сегодня</button><label class="field">Показывать<select id="calendar-mode"><option value="baseline" ${calendarMode==='baseline'?'selected':''}>Исходный план</option><option value="forecast" ${calendarMode==='forecast'?'selected':''}>Текущий прогноз</option></select></label><label class="field">Вид<select id="calendar-view"><option value="month" ${calendarView==='month'?'selected':''}>Месяц</option><option value="agenda" ${calendarView==='agenda'?'selected':''}>Список дней</option></select></label><button id="export-ics">В календарь .ics</button></div>
 <div ${calendarView==='month'?'':'hidden'}><div class="calendar">${cells}</div><p class="calendar-footer">Синий — запланировано · зелёный — все задачи дня завершены · красный — в прошедшем дне осталась работа. Выбери день для подробностей.</p></div>
 <div class="box agenda" ${calendarView==='agenda'?'':'hidden'}>${days.length?days.map(d=>`<div class="agenda-date">${date(d,true)} · ${number(perDay[d].reduce((a,s)=>a+s.hours,0))} ч</div>${perDay[d].map(s=>taskRow(byId[s.id],number(s.hours)+' ч в этот день')).join('')}`).join(''):'<p class="empty">В этом месяце нет работ по выбранному календарю.</p>'}</div>
 <div class="box"><div class="box-title"><h3>${date(selectedDate,true)}</h3><button class="small" data-day-edit="${selectedDate}">Часы этого дня</button></div>${selected.length?selected.map(s=>taskRow(byId[s.id],number(s.hours)+' ч в этот день')).join(''):`<p class="empty">Работа не назначена. ${C.capacity(state.config,selectedDate)===0?'По твоему графику это выходной.':'Возможное ожидание поставки, выдержки или зависимой задачи.'}</p>`}</div>
 <p class="note">Импорт .ics создаёт события на весь день с указанной трудоёмкостью, без выдуманного времени начала. После изменения расписания экспортируй его заново. События — план, их импорт не отмечает выполнение.</p>`;
}
function moduleProgress(id){const tasks=activeTasks().filter(t=>t.module===id),total=tasks.reduce((a,t)=>a+taskCost(t.id),0),earned=tasks.reduce((a,t)=>a+taskCost(t.id)*(progress(t.id).percent||0)/100,0);return {tasks,total,earned,percent:total?100*earned/total:0,done:tasks.length>0&&tasks.every(t=>progress(t.id).percent===100)};}
function renderRoadmap(){
 const shown=D.modules.filter(m=>!taskFilter||m.id===taskFilter);
 $('#panel-roadmap').innerHTML=`<h2>Что мастерская умеет делать</h2><p class="lede">Возможность считается освоенной после завершения и проверки работ направления. Станки остаются средствами для конкретного результата.</p>
 <div class="cap-grid">${D.modules.filter(m=>m.id!=='later').map(m=>{const p=moduleProgress(m.id);return `<div class="cap"><div class="cap-status">${p.done?'<span class="ok-text">✓ Освоено</span>':p.tasks.length?`${number(p.percent)}% · в плане`:'По решению'}</div><strong>${h(m.capability)}</strong></div>`;}).join('')}</div>
 <div class="toolbar"><label class="field">Направление<select id="task-filter"><option value="">Все направления</option>${D.modules.map(m=>`<option value="${m.id}" ${taskFilter===m.id?'selected':''}>${h(m.title)}</option>`).join('')}</select></label><button data-go="settings">Выбрать направления</button></div>
 ${shown.map(m=>{const p=moduleProgress(m.id),ends=p.tasks.map(t=>forecast.finish[t.id]).filter(Boolean).sort(),start=firstForModule(m.id);return `<article class="module ${p.tasks.length?'':'inactive'}"><div class="module-head"><div class="module-number">${m.number}</div><div><h3>${h(m.title)}</h3><p>${h(m.description)}</p><div class="progress" role="progressbar" aria-label="Готовность ${h(m.title)}" aria-valuenow="${Math.round(p.percent)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p.percent}%"></span></div></div><div class="module-stats">${p.tasks.length?`${date(start)} — ${date(ends.at(-1))}<br>${number(p.total)} ч с запасом · ${p.tasks.length} задач`:'Дополнительное направление'}</div></div><details><summary>${p.tasks.length?'Работы, зависимости и критерии готовности':'Условия включения'}</summary>${p.tasks.length?p.tasks.map(t=>taskRow(t)).join(''):`<p class="note">${m.id==='later'?'Выбирай дополнительный инструмент под самостоятельный проект. Эти позиции не включены в календарь и основной бюджет.':'Включи направление в «Мой график». Предшествующие навыки будут добавлены автоматически.'}</p>`}</details></article>`;}).join('')}`;
}
function quoteDetails(item){const q=item.quote;if(!q)return '<span class="placeholder">Местная цена не подтверждена</span>';const total=q.amount===null?null:q.amount*(1+(q.tax||0)/100)*(q.quantity||1);return `<div class="buy-note">${h(q.model||'')} ${q.quantity>1?'× '+q.quantity:''}</div><div class="buy-note">${q.exampleOnly?'Цена малого примера: '+usd(C.quotedUSD(q,state.config.fx))+' · ':''}${total===null?'Запросить цену':q.currency==='ARS'?ars(total):usd(total)}${q.tax?` · включает добавленный IVA ${q.tax}%`:''}</div><div class="buy-note">${link(q.url,q.vendor)} · ${h(q.access==='page'?'страница':q.access==='pvp'?'PVP производителя':'индекс поиска')}</div><div class="buy-note">Поиск ${date(q.checked)}. ${h(q.terms||'Доставка до Эль-Больсона не подтверждена.')}${q.partial?' Часть комплекта: остальное требует сметы.':''}</div>`;}
function renderBudget(){
 const b=C.budget(D,state),moduleSet=new Set(activeTasks().map(t=>t.module));let items=D.catalog.filter(i=>(!buyFilter||i.module===buyFilter)&&(!buyQuery||(i.title+' '+i.note+' '+(i.quote?.model||'')).toLowerCase().includes(buyQuery.toLowerCase())));
 if(buyScope==='active')items=items.filter(i=>(moduleSet.has(i.module)||(i.module==='later'&&state.items[i.id]?.include))&&(!i.optional||state.items[i.id]?.include));if(buyScope==='unknown')items=items.filter(i=>i.kind!=='have'&&state.items[i.id]?.status!=='owned'&&!state.items[i.id]?.exclude&&C.needsQuote(i,state));if(buyScope==='paid')items=items.filter(i=>C.itemActual(i,state)!==null);
 const statuses={planned:'Планируется',ordered:'Заказано',bought:'Куплено',built:'Собрано',tested:'Испытано',mastered:'Освоено',owned:'Уже было'};
 const quoteCount=D.catalog.filter(i=>i.quote?.amount!==null&&i.quote?.amount!==undefined).length;
 const years={};for(const i of b.active){const first=activeTasks().filter(t=>t.items.includes(i.id)).map(t=>forecast.starts[t.id]).sort()[0]||firstForModule(i.module);const y=first?first.slice(0,4):'По решению',v=C.itemBudget(i,state);years[y]??={known:0,unknown:0};if(C.needsQuote(i,state))years[y].unknown++;if(v!==null)years[y].known+=v;}
 $('#panel-budget').innerHTML=`<h2>Аргентинские цены и реальные расходы</h2><p class="lede">Найденные ценовые ориентиры: ${quoteCount}. Для каждого указаны продавец, исходная валюта и условия. Ориентир становится фактическим расходом только после твоей записи.</p>
 <div class="metrics">${metric('Известная часть сметы',usd(b.known),`${b.active.length} позиций выбранного бюджета`)}${metric('Нужна полная смета',String(b.unknown),'Позиции без цены или с неполным комплектом',b.unknown?'negative':'')}${metric('Фактически оплачено',usd(b.actual),`${b.records} записей; включая дополнительные покупки`)}${metric('Курс для ориентиров',number(state.config.fx),'ARS за 1 USD · '+date(state.config.fxDate))}</div>
 <div class="notice">Пересчёт: цена ARS ÷ курс = USD. Исходный ориентир — ${link(D.fx.url,'BNA billete venta')}, 1 USD = 1535 ARS на 09.10.2026, 17:00. Курс редактируется. Исторические покупки пересчитываются по курсу, сохранённому с платежом.</div>
 <details class="box"><summary>Планируемые закупки по годам и ограничения цен</summary><div class="tablewrap" style="margin-top:14px"><table><thead><tr><th>Год по прогнозу</th><th>Известная часть</th><th>Неполная смета</th><th>Годовой ориентир</th></tr></thead><tbody>${Object.entries(years).map(([y,v])=>`<tr><td>${y}</td><td>${usd(v.known)}</td><td>${v.unknown}</td><td>${state.config.annualBudget?`${usd(state.config.annualBudget)}${v.known>state.config.annualBudget?' · превышен уже известной частью':''}`:'Не задан'}</td></tr>`).join('')}</tbody></table></div><p class="note">Дата закупки привязана к первой работе, использующей позицию, либо к началу направления. Суммы рассчитаны по найденным ценам без прогноза инфляции. В свою полную смету позиции включи доставку, запуск и связанные расходники, если они ещё не учтены отдельными строками. Не складывай дважды один и тот же расход. Цены из индекса поиска могут быть устаревшими; наличие и доставку до Эль-Больсона нужно подтвердить. Цена без налога не выдана за итоговую. Примеры товаров не являются окончательным подбором оборудования.</p></details>
 <div class="toolbar"><input type="search" id="buy-search" placeholder="Инструмент, модель или операция" aria-label="Поиск покупок" value="${h(buyQuery)}"><label class="field">Направление<select id="buy-filter"><option value="">Все</option>${D.modules.map(m=>`<option value="${m.id}" ${buyFilter===m.id?'selected':''}>${h(m.title)}</option>`).join('')}</select></label><label class="field">Показать<select id="buy-scope"><option value="active" ${buyScope==='active'?'selected':''}>Основной план</option><option value="all" ${buyScope==='all'?'selected':''}>Весь каталог</option><option value="unknown" ${buyScope==='unknown'?'selected':''}>Требуется смета</option><option value="paid" ${buyScope==='paid'?'selected':''}>Есть платёж</option></select></label><button id="export-csv">Выгрузить .csv</button><span class="note">${items.length} позиций</span></div>
 <div class="tablewrap"><table class="buy-table"><thead><tr><th>Позиция и задача</th><th>Цена в Аргентине</th><th>Факт и состояние</th><th>Учёт</th></tr></thead><tbody>${items.map(i=>{const s=state.items[i.id]||{},est=C.itemBudget(i,state),actual=C.itemActual(i,state);return `<tr><td><div class="buy-name">${h(i.title)}</div><div class="buy-note">${h(modById[i.module].title)} · ${i.kind==='diy'?'Собрать':i.kind==='service'?'Услуга':i.kind==='have'?'Уже есть':'Купить'}${i.optional?' · по решению':''}</div><div class="buy-note">${h(i.note)}</div></td><td><div class="price">${i.kind==='have'||s.status==='owned'?'Уже было':s.exclude?'Отложено':est===null?'Запросить смету':(i.quote?.partial&&s.estimate==null?'от ':'')+usd(est)}</div>${s.estimate!=null?'<div class="buy-note">Твоя смета в USD</div>':''}${quoteDetails(i)}</td><td><span class="pill ${['tested','mastered','owned'].includes(s.status)||i.kind==='have'?'ok':''}">${i.kind==='have'?'Уже было':h(statuses[s.status]||'Планируется')}</span><div class="buy-note">${actual===null?'Платёж не записан':usd(actual)+' · '+date(s.date)}</div>${s.model?`<div class="buy-note">${h(s.model)}</div>`:''}</td><td><button class="small" data-item="${i.id}">Изменить</button></td></tr>`;}).join('')}</tbody></table>${items.length?'':'<div class="box empty">Ничего не найдено. Измени фильтр.</div>'}</div>`;
}
function renderGuide(){
 const cards=[
 ['Как читать календарь','Рабочие часы распределены на одного человека. В каждой задаче есть ожидаемый результат, трудоёмкость и предшественники. Доставка, выдержка клея, сушка и импорт заданы календарным ожиданием. Ожидание не занимает твои рабочие часы: в это время можно делать другие доступные задачи. Сроки поставок — редактируемые допущения.'],
 ['Честное сравнение плана и факта','Исходный план фиксируется отдельно. Прогноз каждый день распределяет оставшийся объём с учётом готовности. Отклонение = принятые плановые часы − часы, запланированные до конца вчерашнего дня. Фактическое время труда показывается отдельно. Новая точка отсчёта — явное действие с сохранением предыдущей версии в истории.'],
 ['Три ЧПУ — три решения о запуске','LowRider удобен для листов и мастер-моделей. PrintNC выбирается под конкретные металлические детали. Токарный можно освоить раньше второго фрезера. Плазма оправдывается объёмом раскроя стали; сначала сравни услугу. Переключение направлений не стирает записи по ним. Не начинай несколько крупных самостоятельных сборок одновременно.'],
 ['Пространство и инфраструктура','Перед покупкой: обмер помещения, путь заноса, проходы, подача самой длинной заготовки, место сборки и хранения. Отдельно запланировать свет, электрику, вытяжку, фильтры и перемещение тяжёлых деталей. Горячие работы, древесная пыль, смолы и покраска не объединяются одним «грязным углом».'],
 ['Пылесос и стружкоотсос','M-пылесос — для подходящего ручного инструмента и уборки. Стационарным станкам нужен расход воздуха по их паспортам. Циклон отделяет стружку, но не заменяет фильтр. Дополнительный очиститель воздуха не заменяет захват у источника. Металлические искры не должны попадать в древесный пылесборник.'],
 ['Дерево и камерная сушка','Первые изделия — из покупной сухой доски. Параллельно небольшая партия воздушной сушки с журналом. Камера — после сравнения цены сухой доски, выхода годного и энергии. Целевая влажность зависит от условий эксплуатации, а не всегда 6–8%. Осушитель и нагрев требуют допустимого температурного режима и независимого аппаратного отключения.'],
 ['Сварка и сжатый воздух','Для стали первым может быть MIG/MAG; DC lift-TIG не заменяет AC TIG для обычных алюминиевых задач. Для TIG — чистый аргон, для MAG стали — подходящая смесь. Вытяжка нужна и для обычной стали. Компрессор выбирается по FAD при рабочем давлении, ПВ и качеству воздуха выбранных инструментов; объём ресивера сам по себе не решает задачу.'],
 ['Окна и строительная панель','Начни с пробной рамы, узла уплотнения и отвода воды; стеклопакет можно заказать. Учебная панель позволяет проверить последовательность сборки и трудозатраты. Переход к несущей конструкции и жилому дому требует местного проекта и проверки узлов специалистом. Финишный нейлер не заменяет конструкционный крепёж.'],
 ['LowRider и PrintNC: проверяемые характеристики','LowRider: стандартная глубина по Z около 50 мм, до 100 мм — с пониженным ложем. Размер стола считать по актуальному калькулятору и местным листам. PrintNC: поле берётся из выбранной CAD-модели (wiki приводит пресет MetalCutter около 625×625 мм и предупреждает об устаревании частей документации). Точность подтверждать тестовыми деталями; замена всех печатных деталей не является самостоятельной целью.'],
 ['Композиты, давление и отделка','Вакуумная выклейка в мешке и формование нагретого пластика — разные процессы. Для мешка нужны подходящий насос, ловушка смолы, плёнки и тест герметичности. Для литья под давлением — заводская камера с допустимым рабочим давлением; не модифицировать сосуд сверлением и сваркой. Покрытия выбираются по SDS, 2К с изоцианатами — отдельная профессиональная технология.'],
 ['Камень, GFRC и плазма','Камень — мокрая работа подходящим инструментом, сбор шлама и защита питания; мокрый способ не отменяет оценку остаточной пыли. Кварцевый агломерат исключён. В цементных композитах нужна AR-фибра. Плазменный стол в этом плане предназначен для стали: при алюминии над водой возможен водород, нужна специально проверенная конструкция.'],
 ['Сборка, покупка и обучение','Ориентир исходного замысла — до 10 000 USD на один станок, а не на всю мастерскую. Самостоятельность, интерес и новые навыки тоже могут оправдывать проект: окупаемость не обязательна для каждого увлечения. Покупка не означает освоение. Используй состояния оборудования: заказано, куплено, собрано, испытано, освоено. Проект закрывается после проверки результата. Оснастка, повторяемость, безопасное закрепление и снижение трудоёмкости — полноценные причины расширения мастерской.']
 ];
 const sources=[['V1 Engineering · LowRider 4','https://docs.v1e.com/lowrider/'],['Калькулятор габаритов LowRider','https://docs.v1e.com/lowrider/calculator/'],['PrintNC · размеры и оговорки','https://wiki.printnc.info/en/v3/planning/sizing'],['PrintNC · актуальные файлы','https://wiki.printnc.info/en/v4/files'],['USDA · сушка и влажность древесины','https://www.fpl.fs.usda.gov/documnts/fplgtr/fplgtr190/chapter_13.pdf'],['HSE · древесная пыль','https://www.hse.gov.uk/woodworking/wooddust.htm'],['HSE · сварочный дым','https://www.hse.gov.uk/welding/welding-controls.htm'],['HSE · изоцианаты','https://www.hse.gov.uk/mvr/bodyshop/isocyanates.htm'],['Smooth-On · камеры давления','https://www.smooth-on.com/support/faq/156/'],['Hypertherm · алюминий и водяной стол','https://www.hypertherm.com/resources/faqs/is-it-okay-to-plasma-cut-aluminum-on-a-water-table/'],['Atlas Copco · подбор компрессора','https://www.atlascopco.com/en-us/compressors/wiki/compressed-air-articles/dimensioning-compressor-installations'],['grblHAL · Plasma/THC','https://github.com/grblHAL/Plugin_plasma'],['BNA · курс для пересчёта','https://www.bna.com.ar/Personas']];
 $('#panel-guide').innerHTML=`<h2>Решения, на которых держится план</h2><p class="lede">Здесь учтены замечания к редакции 2. Подробные паспорта конкретного оборудования остаются обязательным входом в каждый проект.</p><div class="guide-grid">${cards.map(([t,p])=>`<article class="box"><h3>${h(t)}</h3><p>${h(p)}</p></article>`).join('')}</div><div class="box" style="margin-top:22px"><h3>Технические первоисточники</h3><div class="source-list">${sources.map(([t,url])=>link(url,t)).join('')}</div><p class="note">Зарубежные руководства используются как технические источники, а не как утверждение местных правовых требований. Цены и ссылки на аргентинских продавцов находятся в каждой строке покупок.</p></div>`;
}
function renderSettings(){
 const cfg=state.config,days=[['Пн',1],['Вт',2],['Ср',3],['Чт',4],['Пт',5],['Сб',6],['Вс',0]],activeMods=new Set(activeTasks().map(t=>t.module));
 $('#panel-settings').innerHTML=`<h2>Мой реальный график</h2><p class="lede">Задай доступное время. Изменения обновляют прогноз, а исходный календарь сохраняется до явного пересчёта.</p>${loadWarning?`<div class="notice warn">${h(loadWarning)} <button id="recover-raw" class="small">Скачать исходную запись</button></div>`:''}
 <form id="settings-form"><div class="settings-grid"><div class="box"><h3>Время и направления</h3><div class="fields"><label class="field">Дата старта<input name="start" type="date" required min="2000-01-01" max="2090-12-31" value="${cfg.start}"></label><label class="field">Запас к трудоёмкости, %<input name="buffer" type="number" required min="0" max="100" step="1" value="${cfg.buffer}"></label></div><p class="smalltext subtle" style="margin:18px 0 8px">Доступные часы в каждый день недели</p><div class="week-hours">${days.map(([label,n])=>`<label class="field">${label}<input aria-label="Часы ${label}" name="hours-${n}" type="number" min="0" max="16" step="0.25" required value="${cfg.hours[n]}"></label>`).join('')}</div><p class="note">Время печати без участия и ожидание сушки не добавляют рабочие часы. Праздники не исключаются автоматически: отметь свои нерабочие даты.</p><div class="module-options">${D.modules.filter(m=>m.id!=='later').map(m=>`<label class="check"><input name="modules" type="checkbox" value="${m.id}" ${activeMods.has(m.id)?'checked':''} ${m.id==='base'?'disabled':''}>${h(m.title)}</label>`).join('')}</div><p class="note">Предшествующие направления включаются автоматически. Задачи отключённого направления сохраняют факт и заметки.</p></div>
 <div><div class="box"><h3>Курс и денежный ориентир</h3><div class="fields"><label class="field">ARS за 1 USD<input name="fx" type="number" min="0.01" max="10000000" step="0.01" required value="${cfg.fx}"></label><label class="field">Дата курса<input name="fxDate" type="date" required value="${cfg.fxDate}"></label><label class="field full">Годовой бюджет в USD, 0 — не задан<input name="annualBudget" type="number" min="0" max="10000000" step="1" required value="${cfg.annualBudget}"></label></div><p class="note">Курс меняет ориентиры в ARS. Введённые платежи сохраняют свой исторический курс. Годовой бюджет подсвечивает превышения, но сам не откладывает покупки.</p></div>
 <div class="box"><h3>Исключения календаря</h3><div class="row"><input aria-label="Дата исключения" id="exception-date" type="date" value="${TODAY}"><input aria-label="Часы в исключении" id="exception-hours" type="number" min="0" max="16" step="0.25" value="0" style="width:85px"><button type="button" id="add-exception">Добавить</button></div><p class="note">0 часов — пропустить день. Изменение влияет на прогноз; исходный план остаётся видимым.</p><ul class="mini-list">${Object.entries(cfg.exceptions).sort().map(([d,v])=>`<li class="row spread"><span>${date(d)} · ${number(v)} ч</span><button type="button" class="small" data-remove-exception="${d}">Убрать</button></li>`).join('')||'<li class="subtle">Исключений пока нет.</li>'}</ul></div></div></div><div id="settings-error" class="error" role="alert"></div><div class="sticky-actions"><button class="primary" type="submit">Сохранить график и прогноз</button><button type="button" id="rebaseline">Установить новый исходный план</button></div></form>
 <div class="settings-grid" style="margin-top:24px"><div class="box"><h3>Перенос и резервная копия</h3><p class="smalltext">Автосохранение относится к этому браузеру и адресу файла. Для другого компьютера или браузера скачай JSON и импортируй его там. HTML с данными содержит текущий прогресс внутри файла.</p><div class="row"><button id="export-json">Экспорт JSON</button><button id="import-json">Импорт JSON</button><button id="export-html">HTML с моими данными</button><button id="print-plan">Печать / PDF</button><button id="recover-previous">Предыдущее сохранение</button></div><p class="note">Импорт проверяется до применения, предыдущая запись сохраняется. Смена исходного плана не удаляет факт и платежи.</p></div><div class="box"><h3>История исходных планов</h3><p class="smalltext">Текущий: редакция ${state.baseline.revision||1}, создан ${date(state.baseline.created)}. Исходный финиш ${date(state.baseline.end)}.</p><div class="state-history">${state.history.length?state.history.map((b,i)=>`<div class="task-row"><div class="smalltext">Редакция ${b.revision} · ${date(b.created)}<div class="note">Финиш ${date(b.end)}</div></div><button type="button" class="small" data-history="${i}">Скачать</button></div>`).join(''):'<p class="note">Ещё не пересчитывался.</p>'}</div></div></div>`;
}
const renderers={today:renderToday,calendar:renderCalendar,roadmap:renderRoadmap,budget:renderBudget,guide:renderGuide,settings:renderSettings};
function renderCurrent(){renderers[currentTab]();}
function go(tab,focus=false){if(!renderers[tab])return;currentTab=tab;document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!=='panel-'+tab);renderCurrent();if(focus)$('#tab-'+tab).focus();}
function showDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=body;$('#editor').showModal();}
function closeDialog(){$('#editor').close();}
$('#editor').addEventListener('close',()=>{if(pendingExternal){state=pendingExternal;pendingExternal=null;compute();renderHeader();renderCurrent();toast('Загружена запись из другой вкладки');}});
function formNumber(form,key,nullable=false){const val=new FormData(form).get(key);return nullable&&(val===null||val==='')?null:Number(val);}
function editTask(id){
 const t=byId[id],p=progress(id),o=state.overrides[id]||{},blocked=t.deps.filter(d=>progress(d).percent<100);
 showDialog(t.title,`<p class="smalltext subtle">${h(modById[t.module].title)} · исходный срок ${date(state.baseline.finish[id])} · прогноз ${date(forecast.finish[id])}</p><div class="task-outcome"><strong>Готово, когда:</strong> ${h(t.result)}</div>${t.gate?`<div class="notice warn">${h(t.gate)}</div>`:''}<p class="dependencies">Предшественники: ${t.deps.length?t.deps.map(d=>`${progress(d).percent===100?'✓':'○'} ${h(byId[d].title)}`).join('; '):'нет'}</p>
 <form id="task-form" data-id="${id}"><div class="fields"><label class="field">Готовность результата, %<input name="percent" type="number" min="0" max="100" step="1" required value="${p.percent||0}"></label><label class="field">Фактически потрачено, всего часов<input name="actualHours" type="number" min="0" max="100000" step="0.25" required value="${p.actualHours||0}"></label><label class="field">Дата завершения<input name="completed" type="date" value="${p.completed||TODAY}" max="${TODAY}"></label><label class="check" style="align-self:end"><input name="accepted" type="checkbox" ${p.percent===100?'checked':''}>Результат проверен</label><label class="field full">Заметки, измерения и препятствия<textarea name="note" maxlength="6000">${h(p.note||'')}</textarea></label></div><details style="margin-top:15px"><summary>Уточнить оценку или срок ожидания</summary><div class="fields"><label class="field">Работа без запаса, часов<input name="hours" type="number" min="0.25" max="500" step="0.25" required value="${o.hours??t.hours}"></label><label class="field">Ждать после предшественников, дней<input name="lag" type="number" min="0" max="3650" step="1" required value="${o.lag??t.lag}"></label><label class="field full">Не начинать раньше (например, доставка)<input name="notBefore" type="date" max="2090-12-31" value="${o.notBefore||''}"></label></div><p class="note">Уточнение меняет прогноз. В исходном плане останется прежняя оценка до явного пересчёта.</p></details>
 ${t.items.length?`<p class="note" style="margin-top:15px">Подготовить: ${t.items.map(i=>h(itemById[i].title)).join('; ')}.</p>`:''}<div id="task-error" class="error" role="alert"></div><div class="dialog-actions"><button type="button" data-close>Отмена</button><button type="submit" class="primary">Сохранить работу</button></div></form>`);
}
function editItem(id){const item=itemById[id],s=state.items[id]||{};showDialog(item.title,`<p class="smalltext">${h(item.note)}</p>${quoteDetails(item)}<form id="item-form" data-id="${id}"><div class="fields"><label class="field">Состояние<select name="status">${Object.entries({planned:'Планируется',ordered:'Заказано',bought:'Куплено',built:'Собрано',tested:'Испытано',mastered:'Освоено',owned:'Уже было до плана'}).map(([k,v])=>`<option value="${k}" ${(s.status||(item.kind==='have'?'owned':'planned'))===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Модель / поставщик<input name="model" maxlength="300" value="${h(s.model||'')}"></label><label class="field">Фактически оплачено, всего<input name="amount" type="number" min="0" max="1000000000000" step="0.01" value="${s.amount??''}" placeholder="Пусто — не записано"></label><label class="field">Валюта платежа<select name="currency"><option value="USD" ${s.currency!=='ARS'?'selected':''}>USD</option><option value="ARS" ${s.currency==='ARS'?'selected':''}>ARS</option></select></label><label class="field">Дата платежа<input name="date" type="date" value="${s.date||TODAY}" max="${TODAY}"></label><label class="field">Курс на дату платежа, ARS/USD<input name="fx" type="number" min="0.01" max="10000000" step="0.01" required value="${s.fx||state.config.fx}"></label><label class="field">Твоя полная смета запуска, USD<input name="estimate" type="number" min="0" max="1000000000" step="0.01" value="${s.estimate??''}" placeholder="Цена + доставка + запуск"></label><label class="field">Эксплуатация за год, USD<input name="annual" type="number" min="0" max="1000000" step="0.01" value="${s.annual??''}" placeholder="При известной загрузке"></label><label class="field">Цена услуги вместо покупки, USD<input name="outsource" type="number" min="0" max="1000000" step="0.01" value="${s.outsource??''}" placeholder="На твой объём работ"></label><label class="field">Ссылка на свою смету<input name="url" type="url" maxlength="4000" value="${h(s.url||'')}" placeholder="https://…"></label><label class="field full">Комплект, доставка, расходники, комментарий<textarea name="note" maxlength="6000">${h(s.note||'')}</textarea></label><label class="check full"><input name="exclude" type="checkbox" ${s.exclude?'checked':''}>Отложить: исключить из планируемого бюджета</label>${item.optional?`<label class="check full"><input name="include" type="checkbox" ${s.include?'checked':''}>Включить эту дополнительную позицию в бюджет</label>`:''}</div><p class="note">Вводи полную накопленную сумму платежей за эту позицию. При нескольких платежах в разных валютах сведи их в USD по курсу каждого платежа. Пустая сумма отличается от нуля. Состояние оборудования само не создаёт расход.</p><div id="item-error" class="error" role="alert"></div><div class="dialog-actions"><button type="button" data-close>Отмена</button><button class="primary" type="submit">Сохранить учёт</button></div></form>`);}
function editDay(d){showDialog('Доступное время · '+date(d),`<form id="day-form" data-date="${d}"><label class="field">Рабочие часы, 0 — выходной<input name="hours" type="number" required min="0" max="16" step="0.25" value="${C.capacity(state.config,d)}"></label><p class="note">Прогноз изменится. Исходный календарь останется точкой сравнения.</p><div class="error" id="day-error"></div><div class="dialog-actions"><button type="button" data-close>Отмена</button><button type="submit" class="primary">Сохранить день</button></div></form>`);}
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportJSON(){download(JSON.stringify(state,null,2),'workshop-progress-'+TODAY+'.json','application/json');toast('Резервная копия скачана');}
function exportHTML(){const doc=document.documentElement.cloneNode(true);doc.querySelector('#initial-state').textContent=JSON.stringify(state).replace(/</g,'\\u003c');doc.querySelector('#initial-state').dataset.storageId='-copy-'+crypto.randomUUID();doc.querySelector('#editor').removeAttribute('open');doc.querySelector('#toast').hidden=true;download('<!doctype html>\n'+doc.outerHTML,'Мастерская в Эль-Больсоне — мой план.html','text/html;charset=utf-8');toast('HTML с прогрессом скачан');}
function exportCSV(){const columns=['id','Позиция','Направление','Ориентир USD','Неполная цена','Факт USD','Валюта','Сумма','Курс платежа','Дата платежа','Состояние','Модель','Источник','Комментарий'];const csvValue=v=>{let str=String(v??'');if(/^[\s]*[=+@\-]|^[\t\r]/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"';};const rows=D.catalog.map(i=>{const s=state.items[i.id]||{};return [i.id,i.title,modById[i.module].title,C.itemBudget(i,state),C.needsQuote(i,state),C.itemActual(i,state),s.currency,s.amount,s.fx,s.date,s.status,s.model,s.url||i.quote?.url,s.note];});download('\ufeff'+[columns,...rows].map(r=>r.map(csvValue).join(';')).join('\r\n'),'workshop-budget-'+TODAY+'.csv','text/csv;charset=utf-8');}
function exportICS(){const esc=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//El Bolson Workshop//Planner 3//RU','CALSCALE:GREGORIAN'];const now=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z');const sc=calendarSchedule();for(const s of sc.segments){lines.push('BEGIN:VEVENT','UID:'+s.id+'-'+s.date+'-'+calendarMode+'@elbolson-workshop','DTSTAMP:'+now,'DTSTART;VALUE=DATE:'+s.date.replace(/-/g,''),'DTEND;VALUE=DATE:'+C.addDays(s.date,1).replace(/-/g,''),'SUMMARY:'+esc(byId[s.id].title+' · '+number(s.hours)+' ч'),'DESCRIPTION:'+esc(byId[s.id].result+'\n'+(calendarMode==='baseline'?'Исходный план':'Текущий прогноз')),'END:VEVENT');}lines.push('END:VCALENDAR');const encoder=new TextEncoder();const folded=lines.map(l=>{let out='',chunk='',length=0;for(const char of l){const n=encoder.encode(char).length;if(length+n>73){out+=chunk+'\r\n ';chunk='';length=1;}chunk+=char;length+=n;}return out+chunk;}).join('\r\n')+'\r\n';download(folded,'workshop-'+calendarMode+'-'+TODAY+'.ics','text/calendar;charset=utf-8');}
function readSettings(form){const f=new FormData(form),cfg=JSON.parse(JSON.stringify(state.config));cfg.start=f.get('start');cfg.buffer=Number(f.get('buffer'));cfg.fx=Number(f.get('fx'));cfg.fxDate=f.get('fxDate');cfg.annualBudget=Number(f.get('annualBudget'));cfg.hours=Array.from({length:7},(_,i)=>Number(f.get('hours-'+i)));const mods=new Set(['base',...f.getAll('modules')]);function add(m){for(const d of modById[m].requires){if(!mods.has(d)){mods.add(d);add(d);}}}[...mods].forEach(add);cfg.modules=D.modules.filter(m=>mods.has(m.id)).map(m=>m.id);C.validateConfig(cfg,D);return cfg;}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.tab)return go(b.dataset.tab);if(b.dataset.go)return go(b.dataset.go);
 if(b.dataset.task)return editTask(b.dataset.task);if(b.dataset.item)return editItem(b.dataset.item);if(b.dataset.dayEdit)return editDay(b.dataset.dayEdit);if(b.hasAttribute('data-close')||b.id==='dialog-close')return closeDialog();
 if(b.dataset.date){selectedDate=b.dataset.date;renderCalendar();return;}
 if(b.dataset.removeException){delete state.config.exceptions[b.dataset.removeException];changed();return;}
 if(b.dataset.history!==undefined){const base=state.history[Number(b.dataset.history)];download(JSON.stringify(base,null,2),'workshop-baseline-'+base.revision+'.json','application/json');return;}
 switch(b.id){
 case 'theme':{const dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'light':'dark';try{localStorage.setItem(KEY+'-theme',document.documentElement.dataset.theme);}catch{}return;}
 case 'export-top':case 'export-json':exportJSON();return;
 case 'export-html':exportHTML();return;
 case 'import-json':$('#import-file').click();return;
 case 'print-plan':{window.print();return;}
 case 'export-csv':exportCSV();return;
 case 'export-ics':exportICS();return;
 case 'calendar-today':selectedDate=TODAY;month=TODAY.slice(0,7);renderCalendar();return;
 case 'prev-month':case 'next-month':{const d=new Date(C.stamp(month+'-01'));d.setUTCMonth(d.getUTCMonth()+(b.id==='next-month'?1:-1));month=d.toISOString().slice(0,7);renderCalendar();return;}
 case 'add-exception':{const d=$('#exception-date').value,n=Number($('#exception-hours').value);if(!C.validDate(d)||!Number.isFinite(n)||n<0||n>16){$('#settings-error').textContent='Укажи дату и от 0 до 16 часов.';return;}try{state.config=readSettings($('#settings-form'));state.config.exceptions[d]=n;changed();toast('Исключение добавлено, прогноз обновлён');}catch(err){$('#settings-error').textContent=err.message;}return;}
 case 'rebaseline':{try{const cfg=readSettings($('#settings-form'));const temp={...state,config:cfg};const base=C.makeBaseline(D,temp);showDialog('Новая точка отсчёта',`<p>Новый исходный календарь: с ${date(cfg.start)} по ${date(base.end)}. Сравнение будет идти с ним. Предыдущая версия останется в истории.</p><p class="note">Фактические часы, готовность и платежи сохранятся. Пересчёт строит весь выбранный план от указанной даты старта. Для продолжения без обнуления сравнения достаточно сохранить график.</p><div class="dialog-actions"><button data-close>Отмена</button><button class="primary" id="confirm-baseline">Сохранить новую версию</button></div>`);$('#confirm-baseline').onclick=()=>{if(pendingExternal){toast('Закрой редактор, чтобы загрузить запись из другой вкладки');return;}state.history.unshift(state.baseline);state.config=cfg;state.baseline=base;state.revision=base.revision;closeDialog();changed();toast('Новый исходный план сохранён');};}catch(err){$('#settings-error').textContent=err.message;}return;}
 case 'recover-previous':{try{const raw=localStorage.getItem(BACKUP);if(raw)download(raw,'workshop-previous.json','application/json');else toast('Предыдущего сохранения пока нет');}catch{toast('Хранилище браузера недоступно');}return;}
 case 'recover-raw':{const raw=localStorage.getItem(KEY);if(raw)download(raw,'workshop-recovery.json','application/json');else toast('Сохранённой записи нет');return;}
 }
});
document.addEventListener('submit',e=>{
 const form=e.target;if(!['task-form','item-form','settings-form','day-form'].includes(form.id))return;e.preventDefault();
 try{
 if(pendingExternal)throw new Error('Данные изменились в другой вкладке. Закрой редактор: загрузится новая запись.');
 if(form.id==='settings-form'){const cfg=readSettings(form);C.schedule(D,cfg,{progress:state.progress,overrides:state.overrides,start:cfg.start>TODAY?cfg.start:TODAY,forecast:true});state.config=cfg;changed();toast('График сохранён; исходный план не перезаписан');return;}
 if(form.id==='day-form'){const n=formNumber(form,'hours');if(!Number.isFinite(n)||n<0||n>16)throw new Error('Нужно от 0 до 16 часов');state.config.exceptions[form.dataset.date]=n;closeDialog();changed();return;}
 const id=form.dataset.id,fd=new FormData(form);
 if(form.id==='task-form'){
   const percent=formNumber(form,'percent'),completed=fd.get('completed'),prev=progress(id);
   if(percent===100){if(!fd.get('accepted'))throw new Error('Подтверди, что результат проверен.');const missing=byId[id].deps.filter(d=>progress(d).percent!==100);if(missing.length)throw new Error('Сначала отметь предшественников: '+missing.map(d=>byId[d].title).join('; '));if(!C.validDate(completed)||completed>TODAY)throw new Error('Дата завершения должна быть не позже сегодня.');const depDates=byId[id].deps.map(d=>progress(d).completed).filter(Boolean);if(depDates.some(d=>d>completed))throw new Error('Дата завершения раньше предшествующей задачи.');}
   const next=JSON.parse(JSON.stringify(state));next.progress[id]={percent,actualHours:formNumber(form,'actualHours'),completed:percent===100?completed:null,note:fd.get('note'),updated:TODAY};
   if(prev.percent===100&&percent<100){const descendants=D.tasks.filter(t=>t.deps.includes(id)&&progress(t.id).percent===100);if(descendants.length)throw new Error('Сначала открой заново зависимые задачи: '+descendants.map(t=>t.title).join('; '));}
   const override={};if(formNumber(form,'hours')!==byId[id].hours)override.hours=formNumber(form,'hours');if(formNumber(form,'lag')!==byId[id].lag)override.lag=formNumber(form,'lag');if(fd.get('notBefore'))override.notBefore=fd.get('notBefore');if(Object.keys(override).length)next.overrides[id]=override;else delete next.overrides[id];next.log??=[];if(percent!==prev.percent)next.log.push({id,date:TODAY,percent});C.validateState(next,D);C.schedule(D,next.config,{progress:next.progress,overrides:next.overrides,start:next.config.start>TODAY?next.config.start:TODAY,forecast:true});state=next;
 }else{
   const next=JSON.parse(JSON.stringify(state)),amount=formNumber(form,'amount',true),paymentDate=fd.get('date');if(amount!==null&&(!C.validDate(paymentDate)||paymentDate>TODAY))throw new Error('Для платежа нужна дата не позже сегодня.');const url=fd.get('url');if(url&&safeURL(url)==='#')throw new Error('Ссылка должна начинаться с https:// или http://');
   next.items[id]={status:fd.get('status'),model:fd.get('model'),amount,currency:fd.get('currency'),date:amount!==null?paymentDate:null,fx:formNumber(form,'fx'),estimate:formNumber(form,'estimate',true),annual:formNumber(form,'annual',true),outsource:formNumber(form,'outsource',true),url,note:fd.get('note'),exclude:!!fd.get('exclude'),include:!!fd.get('include')};C.validateState(next,D);state=next;
 }
 closeDialog();changed();toast('Сохранено');
 }catch(err){const target=form.id==='settings-form'?'settings-error':form.id==='day-form'?'day-error':form.id==='task-form'?'task-error':'item-error';$('#'+target).textContent=err.message;}
});
document.addEventListener('change',async e=>{
 const el=e.target;switch(el.id){
 case 'calendar-month':if(C.validDate(el.value+'-01')&&el.value>='2000-01'&&el.value<='2190-12'){month=el.value;renderCalendar();}break;
 case 'calendar-mode':calendarMode=el.value;renderCalendar();break;
 case 'calendar-view':calendarView=el.value;renderCalendar();break;
 case 'task-filter':taskFilter=el.value;renderRoadmap();break;
 case 'buy-filter':buyFilter=el.value;renderBudget();break;
 case 'buy-scope':buyScope=el.value;renderBudget();break;
 case 'import-file':{const file=el.files[0];el.value='';if(!file)return;try{if(file.size>5000000)throw new Error('Файл больше 5 МБ.');const candidate=C.validateState(JSON.parse(await file.text()),D);C.schedule(D,candidate.config,{progress:candidate.progress,overrides:candidate.overrides,start:candidate.config.start>TODAY?candidate.config.start:TODAY,forecast:true});showDialog('Импорт прогресса',`<p>Файл: ${h(file.name)}. Заменить текущий прогресс проверенными данными?</p><p class="note">Перед заменой можно скачать текущую копию. Предыдущая запись останется в резерве браузера.</p><div class="dialog-actions"><button id="backup-before-import">Скачать текущую копию</button><button data-close>Отмена</button><button class="primary" id="confirm-import">Применить импорт</button></div>`);$('#backup-before-import').onclick=exportJSON;$('#confirm-import').onclick=()=>{if(pendingExternal){toast('Закрой редактор и повтори импорт после загрузки записи другой вкладки');return;}state=candidate;storageFailed=false;loadWarning='';closeDialog();changed();toast('Прогресс импортирован');};}catch(err){toast('Импорт не применён: '+err.message);}break;}
 }
});
document.addEventListener('input',e=>{if(e.target.id==='buy-search'){buyQuery=e.target.value;const selection=e.target.selectionStart;renderBudget();$('#buy-search').focus();$('#buy-search').setSelectionRange(selection,selection);}});
$('.nav').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...document.querySelectorAll('[data-tab]')],i=tabs.findIndex(t=>t.dataset.tab===currentTab);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();go(tabs[n].dataset.tab,true);});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){if($('#editor').open){try{pendingExternal=C.validateState(JSON.parse(e.newValue),D);}catch{}toast('Данные изменились в другой вкладке. Сохранение заблокировано; закрой редактор, чтобы загрузить новую запись.');return;}try{state=C.validateState(JSON.parse(e.newValue),D);compute();renderHeader();renderCurrent();toast('Подхвачен прогресс из другой вкладки');}catch{toast('Изменение другой вкладки не прошло проверку');}}});
let printOpen=[];
function preparePrint(){
 for(const renderer of Object.values(renderers))renderer();printOpen=[...document.querySelectorAll('main details:not([open])')];printOpen.forEach(e=>e.open=true);
 let appendix=document.getElementById('print-days');if(!appendix){appendix=document.createElement('section');appendix.id='print-days';appendix.className='print-only';document.querySelector('main').append(appendix);}
 const sc=calendarSchedule(),days={};for(const e of sc.segments)(days[e.date]??=[]).push(e);
 appendix.innerHTML='<h2>Полный календарь по дням · '+(calendarMode==='baseline'?'исходный план':'прогноз')+'</h2>'+Object.entries(days).map(([d,ss])=>'<div class="print-day"><strong>'+date(d,true)+'</strong><ul>'+ss.map(e=>'<li>'+h(byId[e.id].title)+' · '+number(e.hours)+' ч</li>').join('')+'</ul></div>').join('');
}
window.addEventListener('beforeprint',preparePrint);
window.addEventListener('afterprint',()=>{printOpen.forEach(e=>e.open=false);printOpen=[];});
function refreshDate(){const now=C.today();if(now!==TODAY&&!$('#editor').open){TODAY=now;compute();renderHeader();renderCurrent();}}
window.addEventListener('focus',refreshDate);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDate();});
try{compute();renderHeader();go('today');}catch(err){$('#panel-today').innerHTML=`<div class="notice warn">Не удалось построить план: ${h(err.message)}. Открой «Мой график» для проверки.</div>`;}
// Exposed for deterministic QA and transparent export; no network calls.
window.WorkshopApp={data:D,getState:()=>JSON.parse(JSON.stringify(state)),getForecast:()=>JSON.parse(JSON.stringify(forecast)),go};
})();
